    // Input shape: [N, C, D, H, W]
    const gert::Shape* in_shape = context->GetInputShape(0);
    uint32_t n = static_cast<uint32_t>(in_shape->GetOriginShape().GetDim(0));
    uint32_t c = static_cast<uint32_t>(in_shape->GetOriginShape().GetDim(1));
    uint32_t d = static_cast<uint32_t>(in_shape->GetOriginShape().GetDim(2));
    uint32_t h = static_cast<uint32_t>(in_shape->GetOriginShape().GetDim(3));
    uint32_t w = static_cast<uint32_t>(in_shape->GetOriginShape().GetDim(4));

    // Read attributes
    uint64_t k_u64 = 0;
    uint64_t s_u64 = 0;
    uint64_t p_u64 = 0;
    bool ceil_mode = false;
    (void)context->GetAttrUInt64("kernel_size", k_u64);
    (void)context->GetAttrUInt64("stride", s_u64);
    (void)context->GetAttrUInt64("padding", p_u64);
    (void)context->GetAttrBool("ceil_mode", ceil_mode);

    uint32_t k = static_cast<uint32_t>(k_u64);
    uint32_t s = static_cast<uint32_t>(s_u64 == 0 ? k_u64 : s_u64);
    uint32_t p = static_cast<uint32_t>(p_u64);

    // Compute output dims
    uint32_t od = out_dim(d, k, s, p, ceil_mode);
    uint32_t oh = out_dim(h, k, s, p, ceil_mode);
    uint32_t ow = out_dim(w, k, s, p, ceil_mode);

    uint64_t totalOut = static_cast<uint64_t>(n) * c * od * oh * ow;
    uint32_t winElems = k * k * k;

    // Fill tiling
    tiling.set_n(n);
    tiling.set_c(c);
    tiling.set_d(d);
    tiling.set_h(h);
    tiling.set_w(w);
    tiling.set_k(k);
    tiling.set_s(s);
    tiling.set_p(p);
    tiling.set_od(od);
    tiling.set_oh(oh);
    tiling.set_ow(ow);
    tiling.set_totalOut(totalOut);
    tiling.set_winElems(winElems);

    // Block dim (heuristic)
    context->SetBlockDim(8);

    // Workspace
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());
    context->SetTilingKey(1);
    return ge::GRAPH_SUCCESS;
}
